window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4eccf8ed517dbf17"]={"versions": [{"id": "FIG-4eccf8ed517dbf17", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Instanzdiagramm im Kontext der AUTOSAR-ECU-Konfigurationsspezifikation (TPS ECU Configuration). Das Diagramm stellt die Definitionshierarchie eines BSW-Moduls (ICU) zwei alternativen Konfigurationswert-Instanziierungen gegenüber, um die Validitätsregeln für symbolische Namenswerte (<code>SymbolicNameValues</code>) und die Generierung von <code>#define</code>-Makros bei mehreren Konfigurationssätzen zu verdeutlichen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in drei Hauptblöcke:</p>\n<ul class=\"fig-list\"><li><strong>DEFINITION</strong> (Moduldefinition aus dem ICU-Metamodell):\n<ul class=\"fig-list\"><li><code>Icu : EcucModuleDef</code> mit Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>.\n</li><li>Enthalten über <code>+container</code>: <code>IcuConfigSet : EcucParamConfContainerDef</code> mit Attribut <code>multipleConfigurationContainer = true</code>.\n</li><li>Enthalten über <code>+subContainer</code>: <code>IcuChannel : EcucParamConfContainerDef</code> mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>.\n</li><li>Enthalten über <code>+parameter</code>: <code>IcuChannelId : EcucIntegerParamDef</code> mit Attributen <code>min = 0</code>, <code>max = 65535</code>, <code>symbolicNameValue = true</code>.\n</li></ul>\n</li><li><strong>Valid Icu configuration</strong> (<code>MyIcu1 : EcucModuleConfigurationValues</code>):\n<ul class=\"fig-list\"><li>Besitzt zwei Konfigurationssätze <code>IcuConfigSet0 : EcucContainerValue</code> und <code>IcuConfigSet1 : EcucContainerValue</code>.\n</li><li>Beide Parametersätze enthalten jeweils einen Untercontainer <code>IcuChannel0 : EcucContainerValue</code>.\n</li><li>Beide Untercontainer weisen dem Parameter <code>IcuChannelId : EcucNumericalParamValue</code> denselben Wert <code>value = 0</code> zu.\n</li></ul>\n</li><li><strong>Invalid Icu configuration</strong> (<code>MyIcu2 : EcucModuleConfigurationValues</code>):\n<ul class=\"fig-list\"><li>Besitzt analog zwei Konfigurationssätze <code>IcuConfigSet0 : EcucContainerValue</code> und <code>IcuConfigSet1 : EcucContainerValue</code> mit Untercontainern <code>IcuChannel0 : EcucContainerValue</code>.\n</li><li>Im ersten Satz hat <code>IcuChannelId : EcucNumericalParamValue</code> den Wert <code>value = 0</code>, im zweiten Satz jedoch <code>value = 1</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Validierungsmodell ohne Laufzeitsequenz. Der Ablauf betrifft den Konfigurations- und Codegenerierungsprozess:</p>\n<ol class=\"fig-list\"><li>Ein BSW-Modul (ICU) definiert konfigurierbare Container und Parameter mit <code>symbolicNameValue = true</code>.\n</li><li>Bei Vorhandensein mehrerer Konfigurationssätze (<code>multipleConfigurationContainer = true</code>) müssen gleichnamige symbolische Entitäten (<code>IcuChannel0</code>) über alle Parametersätze hinweg denselben numerischen Wert für ihren symbolischen Namen (<code>IcuChannelId</code>) erhalten (<code>value = 0</code>).\n</li><li>Weisen verschiedene Konfigurationssätze derselben symbolischen Entität unterschiedliche numerische Werte zu (<code>value = 0</code> vs. <code>value = 1</code>), entsteht ein Konflikt bei der <code>#define</code>-Generierung, wodurch die Konfiguration ungültig ist.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Modellierungsregel für AUTOSAR-ECU-Konfigurationsgeneratoren: Für Parameter mit <code>symbolicNameValue = true</code> wird im generierten C-Header typischerweise ein <code>#define</code>-Makro auf Basis des Kurznamens des übergeordneten Containers erzeugt (z. B. <code>#define IcuChannel0 0</code>). Wenn mehrere Konfigurationssets (<code>multipleConfigurationContainer</code>) existieren, muss die numerische Zuweisung für denselben symbolischen Namen über alle Konfigurationssets konsistent sein, damit der Präprozessor-Bezeichner eindeutig auflösbar bleibt. Andernfalls meldet der Konfigurationsprüfer eine inkonsistente/ungültige Konfiguration.</p>"}, {"id": "FIG-d344e2479d77d3fc", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Instanzdiagramm im Kontext der AUTOSAR-ECU-Konfigurationsspezifikation (TPS ECU Configuration). Das Diagramm stellt die Definitionshierarchie eines BSW-Moduls (ICU) zwei alternativen Konfigurationswert-Instanziierungen gegenüber, um die Validitätsregeln für symbolische Namenswerte (<code>SymbolicNameValues</code>) und die Generierung von <code>#define</code>-Makros bei mehreren Konfigurationssätzen zu verdeutlichen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in drei Hauptblöcke:</p>\n<ul class=\"fig-list\"><li><strong>DEFINITION</strong> (Moduldefinition aus dem ICU-Metamodell):\n<ul class=\"fig-list\"><li><code>Icu : EcucModuleDef</code> mit Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>.\n</li><li>Enthalten über <code>+container</code>: <code>IcuConfigSet : EcucParamConfContainerDef</code>.\n</li><li>Enthalten über <code>+subContainer</code>: <code>IcuChannel : EcucParamConfContainerDef</code> mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>.\n</li><li>Enthalten über <code>+parameter</code>: <code>IcuChannelId : EcucIntegerParamDef</code> mit Attributen <code>min = 0</code>, <code>max = 65535</code>, <code>symbolicNameValue = true</code>.\n</li></ul>\n</li><li><strong>Valid Icu configuration</strong> (<code>MyIcu1 : EcucModuleConfigurationValues</code>):\n<ul class=\"fig-list\"><li>Besitzt zwei Konfigurationssätze <code>IcuConfigSet0 : EcucContainerValue</code> und <code>IcuConfigSet1 : EcucContainerValue</code>.\n</li><li>Beide Parametersätze enthalten jeweils einen Untercontainer <code>IcuChannel0 : EcucContainerValue</code>.\n</li><li>Beide Untercontainer weisen dem Parameter <code>IcuChannelId : EcucNumericalParamValue</code> denselben Wert <code>value = 0</code> zu.\n</li></ul>\n</li><li><strong>Invalid Icu configuration</strong> (<code>MyIcu2 : EcucModuleConfigurationValues</code>):\n<ul class=\"fig-list\"><li>Besitzt analog zwei Konfigurationssätze <code>IcuConfigSet0 : EcucContainerValue</code> und <code>IcuConfigSet1 : EcucContainerValue</code> mit Untercontainern <code>IcuChannel0 : EcucContainerValue</code>.\n</li><li>Im ersten Satz hat <code>IcuChannelId : EcucNumericalParamValue</code> den Wert <code>value = 0</code>, im zweiten Satz jedoch <code>value = 1</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Validierungsmodell ohne Laufzeitsequenz. Der Ablauf betrifft den Konfigurations- und Codegenerierungsprozess:</p>\n<ol class=\"fig-list\"><li>Ein BSW-Modul (ICU) definiert konfigurierbare Container und Parameter mit <code>symbolicNameValue = true</code>.\n</li><li>Bei Vorhandensein mehrerer Konfigurationssätze müssen gleichnamige symbolische Entitäten (<code>IcuChannel0</code>) über alle Parametersätze hinweg denselben numerischen Wert für ihren symbolischen Namen (<code>IcuChannelId</code>) erhalten (<code>value = 0</code>).\n</li><li>Weisen verschiedene Konfigurationssätze derselben symbolischen Entität unterschiedliche numerische Werte zu (<code>value = 0</code> vs. <code>value = 1</code>), entsteht ein Konflikt bei der <code>#define</code>-Generierung, wodurch die Konfiguration ungültig ist.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Modellierungsregel für AUTOSAR-ECU-Konfigurationsgeneratoren: Für Parameter mit <code>symbolicNameValue = true</code> wird im generierten C-Header typischerweise ein <code>#define</code>-Makro auf Basis des Kurznamens des übergeordneten Containers erzeugt (z. B. <code>#define IcuChannel0 0</code>). Wenn mehrere Konfigurationssets existieren, muss die numerische Zuweisung für denselben symbolischen Namen über alle Konfigurationssets konsistent sein, damit der Präprozessor-Bezeichner eindeutig auflösbar bleibt. Andernfalls meldet der Konfigurationsprüfer eine inkonsistente/ungültige Konfiguration.</p>"}], "trans": [{"from": "FIG-4eccf8ed517dbf17", "to": "FIG-d344e2479d77d3fc", "fr": "R4.0.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Containerdefinition <code>IcuConfigSet : EcucParamConfContainerDef</code>: Das Attribut <code>multipleConfigurationContainer = true</code> wurde entfernt.\n</li></ul>"}]};
